// Maps Anthropic's structured-output format onto the neutral response format.
//
// `output_config.format` is the current field. The top-level `output_format` is
// the earlier beta spelling, which Anthropic still accepts, so both are read and
// the current field takes precedence. The neutral contract is OpenAI-shaped and
// requires a schema name that Anthropic never sends, so one is supplied here.
//
// A format that cannot be mapped is reported, not silently dropped. The caller
// asked for constrained output; without a diagnostic, they would receive prose
// with no sign that the constraint never reached the upstream.
fn decode_anthropic_output_format(
    body: &Map<String, Value>,
    diagnostics: &mut Vec<TranslationDiagnostic>,
    policy: &TranslationPolicy,
) -> Result<Option<Value>> {
    let Some(format) = body
        .get("output_config")
        .and_then(Value::as_object)
        .and_then(|config| config.get("format"))
        .or_else(|| body.get("output_format"))
    else {
        return Ok(None);
    };
    let Some(format) = format.as_object() else {
        push_lossy(
            diagnostics,
            policy,
            "Anthropic structured output format is not an object; the requested format was dropped",
        )?;
        return Ok(None);
    };
    if format.get("type").and_then(Value::as_str) != Some("json_schema") {
        push_lossy(
            diagnostics,
            policy,
            "Anthropic structured output maps only a json_schema format; the requested format was dropped",
        )?;
        return Ok(None);
    }
    // A non-object schema would be copied verbatim into the neutral contract and
    // reach the upstream as a malformed `json_schema.schema`, so it is rejected here.
    let Some(schema) = format.get("schema").filter(|schema| schema.is_object()) else {
        push_lossy(
            diagnostics,
            policy,
            "Anthropic structured output requires format.schema to be an object; the requested format was dropped",
        )?;
        return Ok(None);
    };
    Ok(Some(json!({
        "type": "json_schema",
        "json_schema": {
            "name": ANTHROPIC_STRUCTURED_OUTPUT_SCHEMA_NAME,
            "schema": schema.clone(),
        },
    })))
}

